import { readFileSync, writeFileSync, unlinkSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';

const useLocal = process.argv.includes('--local');
const bundleModePath = resolve('src/lib/native-bundle-mode.js');

writeFileSync(
  bundleModePath,
  `// Auto-generated by scripts/use-local-native-bundle.mjs — do not edit
export const LOCAL_NATIVE_BUNDLE = ${useLocal};
`
);
console.log(`Wrote ${bundleModePath} (LOCAL_NATIVE_BUNDLE=${useLocal})`);

const paths = [
  resolve('capacitor.config.json'),
  resolve('ios/App/App/capacitor.config.json'),
];

const baseIos = {
  contentInset: 'automatic',
  backgroundColor: '#ffffff',
};

const hostedIos = {
  ...baseIos,
  allowsLinkPreview: false,
  zoomEnabled: false,
};

for (const configPath of paths) {
  const config = JSON.parse(readFileSync(configPath, 'utf8'));

  if (useLocal) {
    delete config.server;
    config.ios = { ...baseIos };
    console.log(`Local bundle mode (build v4 style): removed server.url from ${configPath}`);
    if (configPath.includes('ios/App/App/capacitor.config.json')) {
      writeFileSync(resolve('ios/App/App/BUNDLED_MODE.txt'), 'bundled\n');
    }
  } else {
    config.server = {
      url: 'https://restorebraine.base44.app',
      cleartext: false,
      allowNavigation: [
        'restorebraine.base44.app',
        'restorebraine.com',
        'www.restorebraine.com',
        'app.base44.com',
        'accounts.google.com',
        'appleid.apple.com',
        'checkout.stripe.com',
        'pay.stripe.com',
        'stripe.com',
        'js.stripe.com',
        'm.stripe.com',
        'hooks.stripe.com',
      ],
    };
    config.ios = { ...hostedIos };
    console.log(`Hosted mode: restored server.url in ${configPath}`);
    const bundledModePath = resolve('ios/App/App/BUNDLED_MODE.txt');
    if (existsSync(bundledModePath)) unlinkSync(bundledModePath);
  }

  writeFileSync(configPath, `${JSON.stringify(config, null, 2)}\n`);
}
